require_once __DIR__.'/config/config.php';require_login();$uid=(int)$_SESSION['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(in_array($action,['Completed','Pending'],true)){$stmt=$conn->prepare('UPDATE reminders SET status=? WHERE id=? AND owner_id=?');$stmt->bind_param('sii',$action,$id,$uid);$stmt->execute();flash('Reminder updated.');}header('Location: reminders.php');exit;}$stmt=$conn->prepare('SELECT r.*,a.animal_code FROM reminders r LEFT JOIN animals a ON a.id=r.animal_id WHERE r.owner_id=? ORDER BY (r.status="Pending") DESC,r.due_date ASC');$stmt->bind_param('i',$uid);$stmt->execute();$rows=$stmt->get_result();$page_title='Reminders';require __DIR__.'/includes/header.php';
?>
<div class="page-actions"><div><p>Plan upcoming activities, review overdue tasks and receive email alerts when tasks are due.</p></div><a class="btn btn-primary" href="reminder_add.php">＋ Create reminder</a></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Due date</th><th>Task</th><th>Animal</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):$late=$r['status']==='Pending'&&$r['due_date']<date('Y-m-d');?><tr><td><?=e(date('d M Y',strtotime($r['due_date'])))?></td><td><strong><?=e($r['title'])?></strong><br><span class="muted"><?=e($r['notes']?:'')?></span></td><td><?=e($r['animal_code']?:'General task')?></td><td><span class="pill <?=$r['status']==='Completed'?'':' '.($late?'danger':'warning')?>"><?=e($late?'Overdue':$r['status'])?></span></td><td><?php if($r['status']==='Pending'):?><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="Completed"><button class="btn btn-light btn-sm">Mark done</button></form><?php else:?>—<?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="empty">No reminders yet. Create a reminder to plan a future task.</td></tr><?php endif;?></tbody></table></div></div>
